327:         public static EpoxyApplication EpoxyPretreatment(EpoxyApplication epoxyApplication, AKRSPoint3D point3D, double angle)
328:         {
329:             // 先克隆一个，避免后续将原数据更改掉了
330:             EpoxyApplication epoxy = ObjectHelper.Clone(epoxyApplication);
331: 
332:             double sizeMaxX = 0;
333:             double sizeMinX = 0;
334:             double sizeMaxY = 0;
335:             double sizeMinY = 0;
336: 
337:             // 找出最大值和最小值，为归一化做准备
338:             for (int i = 0; i < epoxy.DispensePatternParas.Count; i++)
339:             {
340:                 for (int j = 0; j < epoxy.DispensePatternParas[i].Length; j++)
341:                 {
342:                     EpoxyApplicationLocation location = epoxy.DispensePatternParas[i][j];
343:                     if (i == 0 && j == 0)
344:                     {
345:                         sizeMaxX = location.X;
346:                         sizeMinX = location.X;
347:                         sizeMaxY = location.Y;
348:                         sizeMinY = location.Y;
349:                     }
350:                     else
351:                     {
352:                         sizeMaxX = Math.Max(sizeMaxX, location.X);
353:                         sizeMaxY = Math.Max(sizeMaxY, location.Y);
354:                         sizeMinX = Math.Min(sizeMinX, location.X);
355:                         sizeMinY = Math.Min(sizeMinY, location.Y);
356:                     }
357:                 }
358:             }
359: 
360:             double offsetX = (sizeMaxX + sizeMinX) / 2.0;
361:             double offsetY = (sizeMaxY + sizeMinY) / 2.0;
362:             sizeMaxX = sizeMaxX - offsetX;
363:             sizeMaxY = sizeMaxY - offsetY;
364: 
365:             // 归一化
366:             for (int i = 0; i < epoxy.DispensePatternParas.Count; i++)
367:             {
368:                 for (int j = 0; j < epoxy.DispensePatternParas[i].Length; j++)
369:                 {
370:                     EpoxyApplicationLocation location = epoxy.DispensePatternParas[i][j];
371: 
372:                     location.X = (location.X - offsetX) * epoxy.SizeX / sizeMaxX / 2.0;
373: 
374:                     location.Y = (location.Y - offsetY) * epoxy.SizeY / sizeMaxY / 2.0;
375:                 }
376: 
377:                 if (epoxy.DispensePatternParas[i].Length == 2 
378:                     && epoxyApplication.EpoxyApplicationStrategy == EpoxyApplicationTypeEnum.SingleDotOnly)
379:                 {
380:                     epoxy.DispensePatternParas[i][0].X =
381:                         (epoxy.DispensePatternParas[i][0].X + epoxy.DispensePatternParas[i][1].X) / 2.0;
382: 
383:                     epoxy.DispensePatternParas[i][0].Y =
384:                         (epoxy.DispensePatternParas[i][0].Y + epoxy.DispensePatternParas[i][1].Y) / 2.0;
385:                 }
386:             }
387: 
388:             // 速度初始化
389:             for (int i = 0; i < epoxy.DispensePatternParas.Count; i++)
390:             {
391:                 for (int j = 0; j < epoxy.DispensePatternParas[i].Length; j++)
392:                 {
393:                     if (epoxy.DispensePatternParas[i][j].Speed <= 0)
394:                     {
395:                         epoxy.DispensePatternParas[i][j].Speed = 100;
396:                     }
397:                     
398:                     if (epoxy.DispensePatternParas[i][j].Acc <= 0)
399:                     {
400:                         epoxy.DispensePatternParas[i][j].Acc = 1000;
401:                     }
402:                     
403:                     if (epoxy.DispensePatternParas[i][j].Dec <= 0)
404:                     {
405:                         epoxy.DispensePatternParas[i][j].Dec = 1000;
406:                     }
407: 
408:                     epoxy.DispensePatternParas[i][j].Speed =
409:                         epoxy.DispensePatternParas[i][j].Speed * epoxy.SpindleSpeedPercentage / 100.0;
410:                     epoxy.DispensePatternParas[i][j].Acc =
411:                         epoxy.DispensePatternParas[i][j].Acc * epoxy.SpindleSpeedPercentage / 100.0;
412:                     epoxy.DispensePatternParas[i][j].Dec =
413:                         epoxy.DispensePatternParas[i][j].Dec * epoxy.SpindleSpeedPercentage / 100.0;
414: 
415:                     if (double.IsNaN(epoxy.DispensePatternParas[i][j].X))
416:                     {
417:                         epoxy.DispensePatternParas[i][j].X = 0;
418:                     }
419: 
420:                     if (double.IsNaN(epoxy.DispensePatternParas[i][j].Y))
421:                     {
422:                         epoxy.DispensePatternParas[i][j].Y = 0;
423:                     }
424:                 }
425:             }
426: 
427:             // 添加旋转和偏移
428:             for (int i = 0; i < epoxy.DispensePatternParas.Count; i++)
429:             {
430:                 for (int j = 0; j < epoxy.DispensePatternParas[i].Length; j++)
431:                 {
432:                     EpoxyApplicationLocation location = epoxy.DispensePatternParas[i][j];
433: 
434:                     double x = location.X;
435:                     double y = location.Y;
436:                     // 转化成弧度
437:                     double degree = (epoxy.Angle + angle) * Math.PI / 180.0;
438: 
439:                     location.X = x * Math.Cos(degree) - y * Math.Sin(degree) + /*epoxy.OffsetX +*/ point3D.X;
440:                     location.Y = x * Math.Sin(degree) + y * Math.Cos(degree) + /*epoxy.OffsetY*/ + point3D.Y;
441:                     location.Z = location.Z + point3D.Z;
442:                 }
443:             }
444: 
445:             return epoxy;
446:         }

