351:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "开始设置胶压");
352: 
353:                         // 异步设置胶压
354:                         Task task = new Task(
355:                             () =>
356:                                 {
357:                                     if (MachineStateModel.GetInstance().IsDryCycle || this.Program.DispenserProgram.Dispenser.DispenserType == DispenserTypeEnum.PrintingTool)
358:                                     {
359:                                         return;
360:                                     }
361: 
362:                                     this.SetDispensePressure(
363:                                         (int)epoxyApplication.DispensePressure,
