397:                         this.DispenseModule.AxisXYAbsoluteMove(
398:                             epoxyApplication.DispensePatternParas[i][0].X,
399:                             epoxyApplication.DispensePatternParas[i][0].Y);
400: 
401:                         //MotionService.MoveAxesToTargetPosition(
402:                         //    (this.DispenseModule.DispenseAxisX, false, epoxyApplication.DispensePatternParas[i][0].X,
403:                         //        AccuracyMode.HighAccuracy),
404:                         //    (this.DispenseModule.DispenseAxisY, false, epoxyApplication.DispensePatternParas[i][0].Y, AccuracyMode.HighAccuracy));
405: 
406:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "点胶过程中 点胶XY轴插补移动到指令位置");
407:                     }
408: 
409:                     #region 提前开胶
410: 
411:                     // 提前开胶
412:                     if (epoxyApplication.AdvanceOpenDistanceNew != 0)
413:                     {
414:                         // 单步工作
415:                         if (!System1Domain.GetInstance().WaitSingleStep())
416:                         {
417:                             return ExcuteResult.Alarm;
418:                         }
419: 
420:                         this.MoveAxisZToPositionWithoutDelay(
