477:                     #endregion
478: 
479:                     // 如果画胶里面只有两个数且XY相等，则认为是点胶，不开启插补
480:                     if (epoxyApplication.DispensePatternParas[i].Length == 2
481:                         && epoxyApplication.DispensePatternParas[i][0].X
482:                             .CompareTo(epoxyApplication.DispensePatternParas[i][1].X) == 0
483:                         && epoxyApplication.DispensePatternParas[i][0].Y
484:                             .CompareTo(epoxyApplication.DispensePatternParas[i][1].Y) == 0 
485:                         || epoxyApplication.EpoxyApplicationStrategy == EpoxyApplicationTypeEnum.SingleDotOnly)
486:                     {
487:                         #region 点胶
488: 
489:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"开始单颗点胶");
