491:                         // 单步工作
492:                         if (!System1Domain.GetInstance().WaitSingleStep())
493:                         {
494:                             return ExcuteResult.Alarm;
495:                         }
496: 
497:                         if (isDrip)
498:                         {
499:                             this.DispenseModule.OpenDispensingElectric();
500:                         }
501:                         else
502:                         {
503:                             this.DispenseModule.CloseDispensingElectric();
504:                         }
