509: 
510:                         // 保持一定时间,这个在画胶软件里面去设置
511:                         DelayHelper.Delay(epoxyApplication.DispensePatternParas[i][0].DripTime + firstDelay);
512: 
513:                         DispenseRunTimeProvider.RecordTime(
514:                             "系统1点胶流程",
515:                             $"点胶延时{epoxyApplication.DispensePatternParas[i][0].DripTime + firstDelay}");
516: 
517:                         // 点胶完成，关闭点胶阀IO
518:                         this.DispenseModule.CloseDispensingElectric();
519: 
520:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"关闭点胶阀完成");
521: 
522:                         #endregion
523:                     }
524:                     else
525:                     {
526:                         // 单步工作
527:                         if (!System1Domain.GetInstance().WaitSingleStep())
528:                         {
529:                             return ExcuteResult.Alarm;
530:                         }
531: 
532:                         if (this.DispenseModule.GetDispenseXAxis().AxisDrive is ETELAxis)
533:                         {
534:                             iGroup = this.GetIpolGroup();
535: 
536:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"准备开始点胶插补");
537: 
538:                             // 开始插补
539:                             iGroup.ipolBegin();
540: 
541: 
542:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶开始插补");
543: 
544:                             // 设置为绝对坐标系 ，不设置绝对坐标系
545:                             iGroup.ipolSetAbsMode(true, -1);
546: 
547:                             // 连续插补
548:                             for (int j = 0; j < epoxyApplication.DispensePatternParas[i].Length; j++)
549:                             {
550:                                 // 由于第一段是到这个位置的参数，所以需要默认值
