554:                                     iGroup.ipolTanAcceleration(0.01);
555:                                     iGroup.ipolTanDeceleration(0.01);
556: 
557:                                     // 设置抖动时间，不知道什么意思
558:                                     iGroup.ipolTanJerkTime(0.01);
559:                                 }
560:                                 else
561:                                 {
562:                                     // 设置速度,Etel的单位为M/s，外接传入为mm/s,需要转换
