568:                                     iGroup.ipolTanDeceleration(
569:                                         epoxyApplication.DispensePatternParas[i][j - 1].Acc / 1000.0);
570: 
571:                                     iGroup.ipolTanJerkTime(0.01);
572:                                 }
573: 
574:                                 if (epoxyApplication.DispensePatternParas[i][j].OpenGlueFlag)
575:                                 {
576:                                     iGroup.ipolMark2Param(5, 5, 0x0000001, 1000);
577:                                     // 点胶完成，关闭点胶阀IO
578:                                     this.DispenseModule.OpenDispensingElectric();
579:                                 }
580:                                 else
581:                                 {
582:                                     iGroup.ipolMark2Param(5, 5, 0x0010000, 1000);
583:                                     // 点胶完成，关闭点胶阀IO
584:                                     this.DispenseModule.CloseDispensingElectric();
585:                                 }
586: 
587:                                 iGroup.ipolLine(
588:                                     epoxyApplication.DispensePatternParas[i][j].X / 1000,
589:                                     epoxyApplication.DispensePatternParas[i][j].Y / 1000);
590: 
591:                                 // 等待插补结束
592:                                 iGroup.ipolWaitMovement(100000);
593:                             }
594: 
595:                             // 最后关闭插补的IO
596:                              iGroup.ipolMark2Param(5, 5, 0x0010000, 1000);
597:                             // 点胶完成，关闭点胶阀IO
598:                             this.DispenseModule.CloseDispensingElectric();
599: 
600:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"关闭点胶阀完成");
601: 
602:                             // 退出插补模式
603:                             iGroup.ipolEnd();
604: 
605:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶结束插补");
606:                         }
607:                         else
608:                         {
609:                             //this.DispenseModule.DripElectric.SetOutputValue(true);
610: 
611:                             GuGaoDrive.Interpolation(
612:                                 1,
613:                                 epoxyApplication.DispensePatternParas[i],
614:                                 this.DispenseModule.GetDispenseIndex());
615: 
616:                             this.DispenseModule.CloseDispensingElectric();
617: 
618:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶结束插补");
619:                         }
620:                     }
621: 
622:                     #region 一段断尾
623: 
624:                     if (epoxyApplication.TearOff1Open)
625:                     {
626:                         this.DispenseModule.AxisZAbsoluteMove(
627:                             interpolationPos.Z + epoxyApplication.TearOff1Height,
628:                             epoxyApplication.TearOff1Speed);
629: 
630:                         DelayHelper.Delay(epoxyApplication.TearOff1Delay);
631: 
632:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"一段断尾到达指定位置");
633: 
634:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"一段段尾延时{epoxyApplication.TearOff1Delay}ms");
635:                     }
636: 
637:                     #endregion
638: 
639:                     #region 二段断尾
640: 
641:                     if (epoxyApplication.TearOff2Open)
642:                     {
643:                         this.DispenseModule.AxisZAbsoluteMove(
644:                             interpolationPos.Z + epoxyApplication.TearOff2Height,
645:                             epoxyApplication.TearOff2Speed);
646: 
647:                         DelayHelper.Delay(epoxyApplication.TearOff2Delay);
648: 
649:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"二段断尾到达指定位置");
650: 
651:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"二段段尾延时{epoxyApplication.TearOff2Delay}ms");
652:                     }
653: 
654:                     #endregion
655:                 }
656: 
657:                 // 点完胶移动到安全位置
658:                 this.DispenseModule.AxisZAbsoluteMove(preDispenseHeight);
659: 
660:                 DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶动作结束");
661: 
662:                 return ExcuteResult.Success;
663:             }
664:             catch (Exception ex)
665:             {
666:                 AKRSXtraMessageBox.Show(ex.Message + "点胶/画胶出现异常，请联系设备管理人员");
667:                 return ExcuteResult.Fail;
668:             }
669:         }

282:         public bool IsDataReasonAble()
283:         {
284:             for (int i = 0; i < this.DispensePatternParas.Count; i++)
285:             {
286:                 for (int j = 0; j < this.DispensePatternParas[i].Length; j++)
287:                 {
288:                     if (this.DispensePatternParas[i][j].Acc == 0)
289:                     {
290:                         this.DispensePatternParas[i][j].Acc = 100;
291:                     }
292: 
293:                     if (this.DispensePatternParas[i][j].Dec == 0)
294:                     {
295:                         this.DispensePatternParas[i][j].Dec = 100;
296:                     }
297: 
298:                     if (this.DispensePatternParas[i][j].Speed == 0)
299:                     {
300:                         this.DispensePatternParas[i][j].Speed = 10;
301:                     }
302:                 }
303:             }
304: 
305:             for (int i = 0; i < this.DispensePatternParas.Count; i++)
306:             {
307:                 for (int j = 0; j < this.DispensePatternParas[i].Length; j++)
308:                 {
309:                     if (j != this.DispensePatternParas[i].Length - 1)
310:                     {
311:                         if (!DispenserMoveHelper.IsEpoxyDataReasonable(this.DispensePatternParas[i][j].Acc))
312:                         {
313:                             AKRSXtraMessageBox.Show($"线{i + 1} ,点{j + 1} 加速度 超过极限 10000");
314:                             return false;
315:                         }
316: 
317:                         if (!DispenserMoveHelper.IsEpoxyDataReasonable(this.DispensePatternParas[i][j].Dec))
318:                         {
319:                             AKRSXtraMessageBox.Show($"线{i + 1} ,点{j + 1} 减速度 超过极限 10000");
320:                             return false;
321:                         }
322: 
323:                         if (!DispenserMoveHelper.IsEpoxyDataReasonableSpeed(this.DispensePatternParas[i][j].Speed))
324:                         {
325:                             AKRSXtraMessageBox.Show($"线{i + 1} ,点{j + 1} 速度超过极限 1000");
326:                             return false;
327:                         }
328:                     }
329:                 }
330:             }
331: 
332:             return true;
333:         }

