334:         public void InitPatternData(EPEData epeData)
335:         {
336:             // 清空数据
337:             this.EpoxyApplication.DispensePatternParas.Clear();
338: 
339:             List<EPEPointData[]> list = epeData.EpePointList;
340: 
341:             for (int i = 0; i < list.Count; i++)
342:             {
343:                 EpoxyApplicationLocation[] dispenseLocations = new EpoxyApplicationLocation[epeData.EpePointList[i].Length];
344:                 for (int j = 0; j < epeData.EpePointList[i].Length; j++)
345:                 {
346:                     EpoxyApplicationLocation dispenseLocation = new EpoxyApplicationLocation
347:                         {
348:                             X = epeData.EpePointList[i][j].X / 1000,
349:                             Y = epeData.EpePointList[i][j].Y / 1000,
350:                             Acc = epeData.EpePointList[i][j].Info.Acc,
351:                             Speed = epeData.EpePointList[i][j].Info.MaxSpeed,
352:                             AltitudeCompensation = epeData.EpePointList[i][j].Info.AltitudeCompensation,
353:                             Dec = epeData.EpePointList[i][j].Info.Acc,
354:                             DripTime = epeData.EpePointList[i][j].Info.Time,
355:                             AdvanceClose = epeData.EpePointList[i][j].Info.PreDelay,
356:                             LagOpen = epeData.EpePointList[i][j].Info.PostDelay,
357:                             OpenGlueFlag = !epeData.EpePointList[i][j].Info.Dummied
358:                         };
359: 
360:                     dispenseLocations[j] = dispenseLocation;
361:                 }
362: 
363:                 this.EpoxyApplication.DispensePatternParas.Add(dispenseLocations);
364:             }
365: 
366:             DispenserMoveHelper.EpoxyPretreatment(this.EpoxyApplication, new AKRSPoint3D(), 0);
367: 
368:             this.Refresh();
369:         }

109:         public static T Clone<T>(T RealObject)
110:         {
111:             using (Stream objectStream = new MemoryStream())
112:             {
113:                 //利用 System.Runtime.Serialization序列化与反序列化完成引用对象的复制  
114:                 IFormatter formatter = new BinaryFormatter();
115:                 formatter.Serialize(objectStream, RealObject);
116:                 objectStream.Seek(0, SeekOrigin.Begin);
117:                 return (T)formatter.Deserialize(objectStream);
118:             }
119:         }

