300:         public ExcuteResult InterpolationApplication(
301:             EpoxyApplication epoxyApplication,
302:             AKRSPoint3D point,
303:             bool isDrip = true,
304:             bool isPrePlant = false,
305:             double angle = 0)
306:         {
307:             try
308:             {
309:                 DispenseRunTimeProvider.RecordTime("系统1点胶流程", "准备开始点胶");
310: 
311:                 #region 数据准备
312: 
313:                 // 将G0坐标转换到机械坐标
314:                 AKRSPoint3D interpolationPos = this.ConvertG0ToMachinePos(point);
315: 
316:                 // 将位置转换到点胶头
317:                 interpolationPos = System1Domain.GetInstance().DispenseController.GetG0DispensePos(interpolationPos);
318: 
319:                 // 数据处理，归一化
320:                 epoxyApplication = DispenserMoveHelper.EpoxyPretreatment(epoxyApplication, interpolationPos, angle);
321: 
322:                 // 高度补偿
323:                 if (isPrePlant)
324:                 {
325:                     interpolationPos.Z += epoxyApplication.PrePlantOffSetZ;
326:                 }
327:                 else
328:                 {
329:                     interpolationPos.Z += epoxyApplication.OffsetZ;
330:                 }
331: 
332:                 // 移动到准备开始点胶的高度
333:                 double preDispenseHeight = interpolationPos.Z + epoxyApplication.SecurityHeightForEpoxyApplication;
334: 
335:                 #endregion
336:                 
337:                 for (int i = 0; i < epoxyApplication.DispensePatternParas.Count; i++)
338:                 {
339:                     this.PrintEpoxy(epoxyApplication);
340:                     if (i == 0 || this.Program.DispenserProgram.Dispenser.DispenserType == DispenserTypeEnum.PrintingTool)
341:                     {
342:                         #region 移动到第一个点胶点并异步设置胶压
343: 
344:                         // 将这个位置告诉点胶头
345:                         AKRSPoint3D preDispensePos =
346:                             new AKRSPoint3D(
347:                                 epoxyApplication.DispensePatternParas[0][0].X,
348:                                 epoxyApplication.DispensePatternParas[0][0].Y,
349:                                 preDispenseHeight);
350: 
351:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "开始设置胶压");
352: 
353:                         // 异步设置胶压
354:                         Task task = new Task(
355:                             () =>
356:                                 {
357:                                     if (MachineStateModel.GetInstance().IsDryCycle || this.Program.DispenserProgram.Dispenser.DispenserType == DispenserTypeEnum.PrintingTool)
358:                                     {
359:                                         return;
360:                                     }
361: 
362:                                     this.SetDispensePressure(
363:                                         (int)epoxyApplication.DispensePressure,
364:                                         (int)epoxyApplication.Vacuum);
365:                                 });
366: 
367:                         task.Start();
368: 
369:                         // 单步工作
370:                         if (!System1Domain.GetInstance().WaitSingleStep())
371:                         {
372:                             return ExcuteResult.Alarm;
373:                         }
374: 
375:                         // 移动到最开始的位置
376:                         this.MoveToG0Pos3D(this.ConvertMachineToG0Pos(preDispensePos));
377: 
378:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "移动到最开始的位置完成");
379: 
380:                         task.Wait();
381: 
382:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "设置胶压完成");
383: 
384:                         if (MachineStateModel.GetInstance().IsDryCycle)
385:                         {
386:                             return ExcuteResult.Success;
387:                         }
388: 
389:                         #endregion
390:                     }
391:                     else
392:                     {
393:                         this.DispenseModule.AxisZAbsoluteMove(preDispenseHeight);
394: 
395:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "点胶Z轴移动到预点胶位置完成");
396: 
397:                         this.DispenseModule.AxisXYAbsoluteMove(
398:                             epoxyApplication.DispensePatternParas[i][0].X,
399:                             epoxyApplication.DispensePatternParas[i][0].Y);
400: 
401:                         //MotionService.MoveAxesToTargetPosition(
402:                         //    (this.DispenseModule.DispenseAxisX, false, epoxyApplication.DispensePatternParas[i][0].X,
403:                         //        AccuracyMode.HighAccuracy),
404:                         //    (this.DispenseModule.DispenseAxisY, false, epoxyApplication.DispensePatternParas[i][0].Y, AccuracyMode.HighAccuracy));
405: 
406:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "点胶过程中 点胶XY轴插补移动到指令位置");
407:                     }
408: 
409:                     #region 提前开胶
410: 
411:                     // 提前开胶
412:                     if (epoxyApplication.AdvanceOpenDistanceNew != 0)
413:                     {
414:                         // 单步工作
415:                         if (!System1Domain.GetInstance().WaitSingleStep())
416:                         {
417:                             return ExcuteResult.Alarm;
418:                         }
419: 
420:                         this.MoveAxisZToPositionWithoutDelay(
421:                             interpolationPos.Z,
422:                             epoxyApplication.SlowTravelSpeedBeforeDispensing);
423: 
424:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "提前开胶-点胶Z轴开始缓慢下降");
425: 
426:                         while (true)
427:                         {
428:                             // 循环判断有没有到位
429:                             if (this.DispenseModule.GetAxisPos().Z
430:                                 <= interpolationPos.Z + epoxyApplication.AdvanceOpenDistanceNew)
431:                             {
432:                                 this.DispenseModule.OpenDispensingElectric();
433:                                 break;
434:                             }
435: 
436:                             Thread.Sleep(1);
437:                         }
438: 
439:                         this.DispenseModule.AxisZWaitForArrival();
440: 
441:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", "点胶Z轴开始缓慢下降到位");
442:                     }
443:                     else
444:                     {
445:                         this.DispenseModule.AxisZAbsoluteMove(interpolationPos.Z, epoxyApplication.SlowTravelSpeedBeforeDispensing);
446:                     }
447: 
448:                     #endregion
449: 
450:                     #region 滞后运动
451: 
452:                     // 单步工作
453:                     if (!System1Domain.GetInstance().WaitSingleStep())
454:                     {
455:                         return ExcuteResult.Alarm;
456:                     }
457: 
458:                     // 判断是否需要到位等待
459:                     if (epoxyApplication.DispenserLeadTime > 0)
460:                     {
461:                         if (epoxyApplication.IsDispenserLeadTimeOpen)
462:                         {
463:                             this.DispenseModule.OpenDispensingElectric();
464:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", "Z轴移动到位，开始出胶，等待结束");
465:                         }
466:                         else
467:                         {
468:                             this.DispenseModule.CloseDispensingElectric();
469:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", "Z轴移动到位，不出胶，等待结束");
470:                         }
471: 
472:                         Thread.Sleep(epoxyApplication.DispenserLeadTime);
473: 
474:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶前到位等待结束");
475:                     }
476: 
477:                     #endregion
478: 
479:                     // 如果画胶里面只有两个数且XY相等，则认为是点胶，不开启插补
480:                     if (epoxyApplication.DispensePatternParas[i].Length == 2
481:                         && epoxyApplication.DispensePatternParas[i][0].X
482:                             .CompareTo(epoxyApplication.DispensePatternParas[i][1].X) == 0
483:                         && epoxyApplication.DispensePatternParas[i][0].Y
484:                             .CompareTo(epoxyApplication.DispensePatternParas[i][1].Y) == 0 
485:                         || epoxyApplication.EpoxyApplicationStrategy == EpoxyApplicationTypeEnum.SingleDotOnly)
486:                     {
487:                         #region 点胶
488: 
489:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"开始单颗点胶");
490: 
491:                         // 单步工作
492:                         if (!System1Domain.GetInstance().WaitSingleStep())
493:                         {
494:                             return ExcuteResult.Alarm;
495:                         }
496: 
497:                         if (isDrip)
498:                         {
499:                             this.DispenseModule.OpenDispensingElectric();
500:                         }
501:                         else
502:                         {
503:                             this.DispenseModule.CloseDispensingElectric();
504:                         }
505: 
506:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"开启点胶阀完成");
507: 
508:                         int firstDelay = (DispenseRunTimeProvider.IsFirstDispense && !isPrePlant) ? this.DevicePara.DispenseModulePara.FisrtDispenseDelay : 0;
509: 
510:                         // 保持一定时间,这个在画胶软件里面去设置
511:                         DelayHelper.Delay(epoxyApplication.DispensePatternParas[i][0].DripTime + firstDelay);
512: 
513:                         DispenseRunTimeProvider.RecordTime(
514:                             "系统1点胶流程",
515:                             $"点胶延时{epoxyApplication.DispensePatternParas[i][0].DripTime + firstDelay}");
516: 
517:                         // 点胶完成，关闭点胶阀IO
518:                         this.DispenseModule.CloseDispensingElectric();
519: 
520:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"关闭点胶阀完成");
521: 
522:                         #endregion
523:                     }
524:                     else
525:                     {
526:                         // 单步工作
527:                         if (!System1Domain.GetInstance().WaitSingleStep())
528:                         {
529:                             return ExcuteResult.Alarm;
530:                         }
531: 
532:                         if (this.DispenseModule.GetDispenseXAxis().AxisDrive is ETELAxis)
533:                         {
534:                             iGroup = this.GetIpolGroup();
535: 
536:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"准备开始点胶插补");
537: 
538:                             // 开始插补
539:                             iGroup.ipolBegin();
540: 
541: 
542:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶开始插补");
543: 
544:                             // 设置为绝对坐标系 ，不设置绝对坐标系
545:                             iGroup.ipolSetAbsMode(true, -1);
546: 
547:                             // 连续插补
548:                             for (int j = 0; j < epoxyApplication.DispensePatternParas[i].Length; j++)
549:                             {
550:                                 // 由于第一段是到这个位置的参数，所以需要默认值
551:                                 if (j == 0)
552:                                 {
553:                                     iGroup.ipolTanVelocity(0.01);
554:                                     iGroup.ipolTanAcceleration(0.01);
555:                                     iGroup.ipolTanDeceleration(0.01);
556: 
557:                                     // 设置抖动时间，不知道什么意思
558:                                     iGroup.ipolTanJerkTime(0.01);
559:                                 }
560:                                 else
561:                                 {
562:                                     // 设置速度,Etel的单位为M/s，外接传入为mm/s,需要转换
563:                                     iGroup.ipolTanVelocity(epoxyApplication.DispensePatternParas[i][j - 1].Speed / 1000.0);
564: 
565:                                     // 设置加速度
566:                                     iGroup.ipolTanAcceleration(
567:                                         epoxyApplication.DispensePatternParas[i][j - 1].Acc / 1000.0);
568:                                     iGroup.ipolTanDeceleration(
569:                                         epoxyApplication.DispensePatternParas[i][j - 1].Acc / 1000.0);
570: 
571:                                     iGroup.ipolTanJerkTime(0.01);
572:                                 }
573: 
574:                                 if (epoxyApplication.DispensePatternParas[i][j].OpenGlueFlag)
575:                                 {
576:                                     iGroup.ipolMark2Param(5, 5, 0x0000001, 1000);
577:                                     // 点胶完成，关闭点胶阀IO
578:                                     this.DispenseModule.OpenDispensingElectric();
579:                                 }
580:                                 else
581:                                 {
582:                                     iGroup.ipolMark2Param(5, 5, 0x0010000, 1000);
583:                                     // 点胶完成，关闭点胶阀IO
584:                                     this.DispenseModule.CloseDispensingElectric();
585:                                 }
586: 
587:                                 iGroup.ipolLine(
588:                                     epoxyApplication.DispensePatternParas[i][j].X / 1000,
589:                                     epoxyApplication.DispensePatternParas[i][j].Y / 1000);
590: 
591:                                 // 等待插补结束
592:                                 iGroup.ipolWaitMovement(100000);
593:                             }
594: 
595:                             // 最后关闭插补的IO
596:                              iGroup.ipolMark2Param(5, 5, 0x0010000, 1000);
597:                             // 点胶完成，关闭点胶阀IO
598:                             this.DispenseModule.CloseDispensingElectric();
599: 
600:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"关闭点胶阀完成");
601: 
602:                             // 退出插补模式
603:                             iGroup.ipolEnd();
604: 
605:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶结束插补");
606:                         }
607:                         else
608:                         {
609:                             //this.DispenseModule.DripElectric.SetOutputValue(true);
610: 
611:                             GuGaoDrive.Interpolation(
612:                                 1,
613:                                 epoxyApplication.DispensePatternParas[i],
614:                                 this.DispenseModule.GetDispenseIndex());
615: 
616:                             this.DispenseModule.CloseDispensingElectric();
617: 
618:                             DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶结束插补");
619:                         }
620:                     }
621: 
622:                     #region 一段断尾
623: 
624:                     if (epoxyApplication.TearOff1Open)
625:                     {
626:                         this.DispenseModule.AxisZAbsoluteMove(
627:                             interpolationPos.Z + epoxyApplication.TearOff1Height,
628:                             epoxyApplication.TearOff1Speed);
629: 
630:                         DelayHelper.Delay(epoxyApplication.TearOff1Delay);
631: 
632:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"一段断尾到达指定位置");
633: 
634:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"一段段尾延时{epoxyApplication.TearOff1Delay}ms");
635:                     }
636: 
637:                     #endregion
638: 
639:                     #region 二段断尾
640: 
641:                     if (epoxyApplication.TearOff2Open)
642:                     {
643:                         this.DispenseModule.AxisZAbsoluteMove(
644:                             interpolationPos.Z + epoxyApplication.TearOff2Height,
645:                             epoxyApplication.TearOff2Speed);
646: 
647:                         DelayHelper.Delay(epoxyApplication.TearOff2Delay);
648: 
649:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"二段断尾到达指定位置");
650: 
651:                         DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"二段段尾延时{epoxyApplication.TearOff2Delay}ms");
652:                     }
653: 
654:                     #endregion
655:                 }
656: 
657:                 // 点完胶移动到安全位置
658:                 this.DispenseModule.AxisZAbsoluteMove(preDispenseHeight);
659: 
660:                 DispenseRunTimeProvider.RecordTime("系统1点胶流程", $"点胶动作结束");
661: 
662:                 return ExcuteResult.Success;
663:             }
664:             catch (Exception ex)
665:             {
666:                 AKRSXtraMessageBox.Show(ex.Message + "点胶/画胶出现异常，请联系设备管理人员");
667:                 return ExcuteResult.Fail;
668:             }
669:         }

675:         private void PrintEpoxy(EpoxyApplication epoxyApplication)
676:         {
677:             if (MachineHardwareConfiguration.GetInstance().IsSystem1ConfigPrintingTool
678:                 && this.Program.DispenserProgram.Dispenser.DispenserType == DispenserTypeEnum.PrintingTool)
679:             {
680:                 // 停止蘸胶盘转动
681:                 this.PrintToolStop();
682:                 DispenseRunTimeProvider.RecordTime("系统1蘸胶流程", $"停止蘸胶盘转动");
683: 
684:                 AKRSPoint3D printingToolPos = DispenseDevicePara.GetInstance().DispenserPara.PrintingToolPos;
685: 
686:                 AKRSPoint3D prePrintingToolPos = new AKRSPoint3D(
687:                     printingToolPos.X,
688:                     printingToolPos.Y,
689:                     printingToolPos.Z + epoxyApplication.PrintSlowDownHeight);
690: 
691:                 // 移动到预蘸胶位置
692:                 this.MoveToG0Pos3D(prePrintingToolPos);
693: 
694:                 DispenseRunTimeProvider.RecordTime("系统1蘸胶流程", $"移动到预蘸胶位置{prePrintingToolPos}完成");
695: 
696:                 double preHeight = this.ConvertG0ToMachinePos(printingToolPos).Z;
697: 
698:                 // 轴缓慢下降
699:                 this.DispenseModule.AxisZAbsoluteMove(preHeight, epoxyApplication.PrintSlowDownSpeed);
700: 
701:                 DispenseRunTimeProvider.RecordTime("系统1蘸胶流程", $"移动蘸胶高度{preHeight},速度{epoxyApplication.PrintSlowDownSpeed}完成");
702: 
703:                 // 停留
704:                 DelayHelper.Delay(epoxyApplication.PrintDelayTime);
705: 
706:                 DispenseRunTimeProvider.RecordTime("系统1蘸胶流程", $"移动蘸胶停留{epoxyApplication.PrintDelayTime}完成");
707: 
708:                 // 轴缓慢上升
709:                 this.DispenseModule.AxisZAbsoluteMove(
710:                     this.ConvertG0ToMachinePos(printingToolPos).Z + epoxyApplication.PrintSlowUpHeight, epoxyApplication.PrintSlowUpSpeed);
711:                 
712:                 DispenseRunTimeProvider.RecordTime("系统1蘸胶流程", $"移动蘸胶高度{this.ConvertG0ToMachinePos(printingToolPos).Z + epoxyApplication.PrintSlowUpHeight},速度{epoxyApplication.PrintSlowUpSpeed}完成");
713: 
714:                 // 停留
715:                 DelayHelper.Delay(epoxyApplication.PrintSlowUpDelayTime);
716: 
717:                 DispenseRunTimeProvider.RecordTime("系统1蘸胶流程", $"移动预蘸胶停留{epoxyApplication.PrintSlowUpDelayTime}完成");
718: 
719:                 // 停止蘸胶盘转动
720:                 this.PrintToolContinueMove();
721: 
722:                 DispenseRunTimeProvider.RecordTime("系统1蘸胶流程", $"蘸胶完成，蘸胶盘继续转动");
723:             }
724:         }

