854:         public void SetDispensePressure(double dispensePressure, double vacuum)
855:         {
856:             try
857:             {
858:                 // 如果不连接点胶器直接返回
859:                 if (!this.DevicePara.DispenseModulePara.IsLinkDispenser)
860:                 {
861:                     return;
862:                 }
863: 
864:                 DispenseRunTimeProvider.RecordTime("系统1胶压流程", $"准备设置胶压{dispensePressure}，负压{vacuum}");
865: 
866:                 // 总胶压 = 输入胶压 + 补偿胶压
867:                 double dispensePressureTotal = dispensePressure + this.DevicePara.DispenseModulePara.GluePressCompensation;
868: 
869:                 DispenseRunTimeProvider.RecordTime("系统1胶压流程", $"补偿后胶压{dispensePressureTotal}，负压{vacuum}");
870: 
871:                 // 判断是否超过总胶压
872:                 if (dispensePressureTotal > this.DevicePara.DispenseModulePara.DispenserMaxValue)
873:                 {
874:                     dispensePressureTotal = this.DevicePara.DispenseModulePara.DispenserMaxValue;
875: 
876:                     DispenseRunTimeProvider.RecordTime("系统1胶压流程", $"胶压过大，改为最大胶压{dispensePressureTotal}，负压{vacuum}");
877:                 }
878: 
879:                 // 判断是否低于最低气压
880:                 if (dispensePressureTotal < 30)
881:                 {
882:                     dispensePressureTotal = 30;
883:                     DispenseRunTimeProvider.RecordTime("系统1胶压流程", $"胶压过小，改为最小胶压{dispensePressureTotal}，负压{vacuum}");
884:                 }
885: 
886:                 this.DispenseModule.SetDispensePressure(dispensePressureTotal, vacuum);
887:             }
888:             catch
889:             {
890:                 throw new Exception("设置点胶阀参数出现问题，请修改后重试");
891:             }
892:         }

