131:         private void CloseDispenseHeightMeasurementCylinderAndDelay(int delay)
132:         {
133:         RetryCommand:
134:             // 关闭点胶气缸
135:             this.measureHeightModule.CloseDispenseAltimemetryCyclinder();
136: 
137:             DateTime dateTime = DateTime.Now;
138:             while (!this.measureHeightModule.IsDispenseAltimemetryCyclinderClosed())
139:             {
140:                 // 如果在规定时间还没收到信号则报警
141:                 if ((DateTime.Now - dateTime).TotalMilliseconds > delay)
142:                 {
143:                     DialogResult dialogResult = AKRSMessageBoxExt.Show(
144:                        $"点胶测高气缸收回失败，请选择如何处理\n\r" +
145:                        $"重试: 重新收回点胶测高气缸\n\r" +
146:                        $"退出: 设备停止",
147:                        "点胶气缸收回失败报警",
148:                        new string[] { "重试", "退出" },
149:                        new DialogResult[] { DialogResult.Retry, DialogResult.Abort },
150:                        AlarmLevel.SecondLevel);
151: 
152:                     if (dialogResult == DialogResult.Retry)
153:                     {
154:                         goto RetryCommand;
155:                     }
156:                     else
157:                     {
158:                         throw new Exception("点胶测高气缸收回失败");
159:                     }
160:                 }
161: 
162:                 Thread.Sleep(10);
163:             }
164:         }

